function answer(bin){if(state.feedback||state.index>=state.questions.length)return;const q=state.questions[state.index],correct=bin===q.bin;state.feedback={correct,text:correct?`分类正确！${q.reason}`:`这次需要放入「${q.bin}」。${q.reason}`};if(correct)state.score+=10;commit()}
function render(){const q=state.questions[state.index];$('#app').innerHTML=`<div class="stats">${stat('挑战进度',`${Math.min(state.index+1,state.questions.length)} / ${state.questions.length}`)}${stat('本轮积分',state.score)}${stat('完成轮次',state.board.length)}</div><div class="grid"><div>${panel(q?'这件物品应该去哪里？':'挑战完成',q?`<div id="rubbish" draggable="true" class="panel tint" style="text-align:center"><div class="big-emoji">${q.icon}</div><h2>${esc(q.name)}</h2><small>拖入分类桶，或直接点选下方分类桶</small></div><div class="bins">${state.bins.map(b=>`<button class="bin" data-action="${b}" ${state.feedback?'disabled':''}>${b}</button>`).join('')}</div>${state.feedback?`<div class="result" style="margin-top:20px">${esc(state.feedback.text)}</div><button id="next" class="primary" style="margin-top:15px">${state.index===state.questions.length-1?'查看本轮成绩':'下一件物品'}</button>`:''}`:`<h2>本轮 ${state.score} / ${state.questions.length*10} 分</h2><p>挑一道答错的题，解释物品状态为什么会改变分类。</p><button id="restart" class="primary">再挑战一次</button>`)}${panel('给家人设计一道题',`<form id="question" class="stack">${field('物品名称','name','text','','required maxlength="40"')}${select('正确分类','bin',state.bins)}${field('解释分类理由','reason','text','','required maxlength="150"')}<button>加入下一轮题库</button></form>`)}</div><div>${panel('家庭积分榜',state.board.slice().sort((a,b)=>b.score/b.max-a.score/a.max).map((x,i)=>`<div class="item"><span>${i+1}. 第 ${x.round} 轮</span><strong>${x.score}/${x.max}</strong></div>`).join('')||empty('完成一轮后，成绩会出现在这里。'),'tint')}${panel('分类观察',`<p>看材质，也看物品的状态。清空内容物、保持清洁等条件，可能影响投放方式。</p><p class="notice">题库采用课堂四分类示例；实际投放以当地标识为准。自编题在下一轮生效。</p>`)}</div></div>`;
actions('[data-action]',answer);if(q){$('#rubbish').ondragstart=e=>e.dataTransfer.setData('text/plain','rubbish');$$('.bin').forEach(b=>{b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();if(e.dataTransfer.getData('text/plain')==='rubbish')answer(b.dataset.action)}})}on('next',()=>{state.index++;state.feedback=null;if(state.index===state.questions.length)state.board.push({player:state._product?.player||"玩家 A",round:state.board.length+1,score:state.score,max:state.questions.length*10});commit()});on('restart',()=>{state.questions=[...clone(seed.questions),...clone(state.custom)];state.index=0;state.score=0;state.feedback=null;commit()});form('question',v=>{state.custom.push({...v,icon:'📦'});save();toast('自编题已保存，下一轮加入')})}render();
